alter table public.payment_approval_requests add column if not exists sale_credit_email text;
alter table public.payment_approval_requests add column if not exists sale_credit_confirmed_by_email text;
alter table public.payment_approval_requests add column if not exists sale_credit_confirmed_at timestamptz;
create or replace function public.cpcm_confirm_payment_sale_credit(target_approval_request_id uuid,target_employee_email text) returns jsonb language plpgsql security invoker set search_path=public as $$ declare req public.payment_approval_requests%rowtype; staff_count integer; begin if lower(coalesce(auth.jwt()->>'email',''))<>'afinch2678@gmail.com' then raise exception 'Admin only'; end if; select count(*) into staff_count from public.app_users where lower(email)=lower(target_employee_email) and lower(coalesce(role,''))='employee' and coalesce(is_active,true)=true and coalesce(is_approved,true)=true; if staff_count<>1 then raise exception 'Active approved employee not found'; end if; select * into req from public.payment_approval_requests where id=target_approval_request_id for update; if not found then raise exception 'Payment request not found'; end if; if lower(coalesce(req.status,''))<>'pending' then raise exception 'Sale credit can only be confirmed before Admin processes a pending payment'; end if; update public.payment_approval_requests set sale_credit_email=lower(target_employee_email),sale_credit_confirmed_by_email=lower(auth.jwt()->>'email'),sale_credit_confirmed_at=now(),updated_at=now() where id=req.id; return jsonb_build_object('ok',true,'approval_request_id',req.id,'sale_credit_email',lower(target_employee_email)); end $$;
revoke execute on function public.cpcm_confirm_payment_sale_credit(uuid,text) from public,anon; grant execute on function public.cpcm_confirm_payment_sale_credit(uuid,text) to authenticated;
create or replace function public.cpcm_commission_from_approved_payment() returns trigger language plpgsql security definer set search_path=public as $$ declare led public.payments_ledger%rowtype; rate numeric; earned numeric; credit_email text; begin if new.ledger_id is null or new.reviewed_by_email is null or lower(coalesce(new.status,'')) not in ('approved','completed','paid') then return new; end if; if exists(select 1 from public.employee_commission_earnings where approval_request_id=new.id) then return new; end if; credit_email:=lower(coalesce(new.sale_credit_email,'')); if credit_email='' or new.sale_credit_confirmed_by_email is null or new.sale_credit_confirmed_at is null then return new; end if; select * into led from public.payments_ledger where id=new.ledger_id; if not found or lower(coalesce(led.status,'')) not in ('completed','paid','settled','processed','success') or lower(coalesce(led.gateway_provider,''))<>'nmi' or coalesce(led.gateway_transaction_id,'')='' then return new; end if; select commission_rate into rate from public.app_users where lower(email)=credit_email and lower(coalesce(role,''))='employee' and coalesce(is_active,true)=true and coalesce(is_approved,true)=true; if rate is null then return new; end if; earned:=round(coalesce(led.amount,led.payment_amount,0)*rate/100,2); insert into public.employee_commission_earnings(ledger_id,approval_request_id,employee_email,gross_amount,commission_rate,earned_amount,status,approved_by_email,approved_at) values(led.id,new.id,credit_email,coalesce(led.amount,led.payment_amount,0),rate,earned,'Earned',lower(new.reviewed_by_email),coalesce(new.reviewed_at,led.paid_at,led.created_at,now())) on conflict do nothing; return new; end $$;
create or replace function public.cpcm_record_approved_commission(target_approval_request_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare req public.payment_approval_requests%rowtype; led public.payments_ledger%rowtype; rate numeric; eid uuid; earned numeric; actor text:=lower(coalesce(auth.jwt()->>'email','')); credit_email text; begin if actor<>'afinch2678@gmail.com' then raise exception 'Admin only'; end if; select * into req from public.payment_approval_requests where id=target_approval_request_id for update; if not found then raise exception 'Approval request not found'; end if; if lower(coalesce(req.status,'')) not in ('approved','completed','paid') or req.ledger_id is null or req.reviewed_by_email is null then raise exception 'Payment has not been approved and finalized by Admin'; end if; credit_email:=lower(coalesce(req.sale_credit_email,'')); if credit_email='' or req.sale_credit_confirmed_by_email is null then raise exception 'Admin must confirm which employee got the sale'; end if; select * into led from public.payments_ledger where id=req.ledger_id; if not found then raise exception 'Approved ledger entry not found'; end if; if lower(coalesce(led.status,'')) not in ('completed','paid','settled','processed','success') or lower(coalesce(led.gateway_provider,''))<>'nmi' or coalesce(led.gateway_transaction_id,'')='' then raise exception 'Ledger is not a finalized approved NMI payment'; end if; select commission_rate into rate from public.app_users where lower(email)=credit_email and lower(coalesce(role,''))='employee' and coalesce(is_active,true)=true and coalesce(is_approved,true)=true; if not found then raise exception 'Credited employee not found'; end if; earned:=round(coalesce(led.amount,led.payment_amount,0)*rate/100,2); insert into public.employee_commission_earnings(ledger_id,approval_request_id,employee_email,gross_amount,commission_rate,earned_amount,status,approved_by_email,approved_at) values(led.id,req.id,credit_email,coalesce(led.amount,led.payment_amount,0),rate,earned,'Earned',lower(req.reviewed_by_email),coalesce(req.reviewed_at,led.paid_at,led.created_at,now())) on conflict(approval_request_id) do nothing returning id into eid; if eid is null then select id into eid from public.employee_commission_earnings where approval_request_id=req.id; end if; return jsonb_build_object('ok',true,'earning_id',eid,'employee_email',credit_email,'gross_amount',coalesce(led.amount,led.payment_amount,0),'commission_rate',rate,'earned_amount',earned); end $$;
